function kthSmallestInGrid(grid: number[][], k: number): number {
  // heap of [value, row, col], smallest value on top
  const h: [number, number, number][] = [];
  const up = (i: number) => { while (i > 0) { const p = (i - 1) >> 1; if (h[p][0] <= h[i][0]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
  const down = (i: number) => {
    for (;;) {
      let m = i; const l = 2 * i + 1, r = l + 1;
      if (l < h.length && h[l][0] < h[m][0]) m = l;
      if (r < h.length && h[r][0] < h[m][0]) m = r;
      if (m === i) return;
      [h[m], h[i]] = [h[i], h[m]]; i = m;
    }
  };
  for (let i = 0; i < grid.length; i++) { h.push([grid[i][0], i, 0]); up(h.length - 1); }
  for (let t = 1; t < k; t++) {
    const [, i, j] = h[0];
    if (j + 1 < grid.length) h[0] = [grid[i][j + 1], i, j + 1];
    else { const last = h.pop()!; if (h.length) h[0] = last; }
    down(0);
  }
  return h[0][0];
}

