function kthSmallestInGrid(grid: number[][], k: number): number {
  const n = grid.length;
  const countAtMost = (x: number) => {
    let r = n - 1, c = 0, cnt = 0;
    while (r >= 0 && c < n) {
      if (grid[r][c] <= x) { cnt += r + 1; c++; }
      else r--;
    }
    return cnt;
  };
  let lo = grid[0][0], hi = grid[n - 1][n - 1];
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (countAtMost(mid) < k) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

