    def kthSmallestInGrid(self, grid: List[List[int]], k: int) -> int:
        n = len(grid)

        def count_at_most(x):
            r, c, cnt = n - 1, 0, 0
            while r >= 0 and c < n:
                if grid[r][c] <= x:
                    cnt += r + 1
                    c += 1
                else:
                    r -= 1
            return cnt

        lo, hi = grid[0][0], grid[-1][-1]
        while lo < hi:
            mid = (lo + hi) // 2
            if count_at_most(mid) < k:
                lo = mid + 1
            else:
                hi = mid
        return lo

